  'errori.java-import.dove': 'Look at the top of the file, above the class, where the `import` lines are.',
  'errori.java-import.cosa-2': 'This class',
  'errori.java-import.cosa-3': `, that is \`import java.util.{nome};\``,
  'errori.java-import.cosa': `{nome} lives in a package of the Java library: to use it you need the \`import\` at the top of the file{nome2}. Check upper and lower case too.`,
  'errori.java-import.concetto': 'import in Java',
  'errori.java-nome-file.etichetta': 'file name and class name differ',
