  'errori.java-irraggiungibile.cosa': 'Before this line there\'s a `return`, a `break`, a `continue` or a loop that never ends: from there the program never gets here. Remove it or move it earlier.',
  'errori.java-irraggiungibile.concetto': 'program flow',
